<?php
require_once __DIR__.'/../config/auth.php'; require_admin(); $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); try {
    if (isset($_POST['excluir'])) { db()->prepare('DELETE FROM materiais_estudo WHERE id=?')->execute([(int)$_POST['id']]); flash('success','Material removido.'); redirect('admin/estudos.php'); }
    $titulo=trim($_POST['titulo']);$disciplina=trim($_POST['disciplina']);
    if(!$titulo||!$disciplina) throw new RuntimeException('Título e disciplina são obrigatórios.');
    $link=trim($_POST['link_externo']); if($link && !filter_var($link,FILTER_VALIDATE_URL)) throw new RuntimeException('Informe um link válido.');
    $pdf=upload_pdf($_FILES['arquivo_pdf']);
    if(!$pdf&&!$link) throw new RuntimeException('Envie um PDF ou informe um link de estudo.');
    db()->prepare('INSERT INTO materiais_estudo(titulo,disciplina,descricao,link_externo,arquivo_pdf,criado_por) VALUES(?,?,?,?,?,?)')->execute([$titulo,$disciplina,trim($_POST['descricao']),$link,$pdf,user()['id']]);
    flash('success','Material de estudo publicado.'); redirect('admin/estudos.php');
}catch(Throwable $e){$error=$e->getMessage();}}
$materials=db()->query('SELECT m.*,u.nome autor FROM materiais_estudo m JOIN usuarios u ON u.id=m.criado_por ORDER BY m.created_at DESC')->fetchAll();
$pageTitle='Estudos';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';
?><div class="dashboard-cards"><form class="panel" method="post" enctype="multipart/form-data" style="margin:0;grid-column:span 1"><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><?=csrf_field()?><h2>Publicar material</h2><div class="form-group"><label>Título</label><input required name="titulo" placeholder="Ex.: Revisão para prova de Matemática"></div><div class="form-group"><label>Disciplina</label><input required name="disciplina" placeholder="Ex.: Matemática"></div><div class="form-group"><label>Descrição ou orientação</label><textarea name="descricao"></textarea></div><div class="form-group"><label>PDF (até 20 MB)</label><input type="file" name="arquivo_pdf" accept="application/pdf,.pdf"></div><div class="form-group"><label>ou link externo</label><input type="url" name="link_externo" placeholder="https://..."></div><button class="btn">Publicar material</button></form><section class="panel" style="margin:0;grid-column:span 2"><h2>Materiais publicados</h2><div class="table-wrap"><table><thead><tr><th>Título</th><th>Disciplina</th><th>Formato</th><th>Publicado por</th><th></th></tr></thead><tbody><?php foreach($materials as $m):?><tr><td><b><?=e($m['titulo'])?></b></td><td><?=e($m['disciplina'])?></td><td><?=$m['arquivo_pdf']?'PDF': 'Link'?></td><td><?=e($m['autor'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$m['id']?>"><input type="hidden" name="excluir" value="1"><button class="btn btn-small btn-danger" data-confirm="Remover este material?">Remover</button></form></td></tr><?php endforeach;?><?php if(!$materials):?><tr><td colspan="5" class="empty">Nenhum material publicado ainda.</td></tr><?php endif;?></tbody></table></div></section></div><?php require __DIR__.'/../includes/dashboard-footer.php';?>
